function formatModuleTime(ts) { if (!Number.isFinite(ts)) return ""; const d = new Date(ts), pad = (n) => String(n).padStart(2, "0"); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}`; }
