document.querySelectorAll(".tool-button").forEach((b) => b.addEventListener("click", () => setTool(b.dataset.tool)));
document.querySelector(".topbar-groups").addEventListener("click", (e) => { const a = e.target.closest("[data-action]")?.dataset.action; if (a === "undo") undo(); if (a === "redo") redo(); if (a === "export") exportWorkflow(); if (a === "save") { saveLocal(); showToast("已保存到本机"); } if (a === "save-module") saveSelectionAsModule(); if (a === "open-modules") openModuleModal(); });
document.querySelector(".statusbar").addEventListener("click", (e) => { const a = e.target.closest("[data-action]")?.dataset.action; if (a === "zoom-out") stepZoom("out"); if (a === "zoom-in") stepZoom("in"); if (a === "zoom-reset") resetView(); });
canvasTabs.addEventListener("click", (e) => { const add = e.target.closest('[data-action="new-canvas"]'), close = e.target.closest(".tab-close"), tab = e.target.closest(".canvas-tab"); if (add) return createCanvas(); if (!tab) return; if (close) return closeCanvas(tab.dataset.canvasId); if (state.activeCanvasId === tab.dataset.canvasId) return; if (moduleEditing) return showToast(`模块「${moduleEditing.name}」正在编辑中，请先「保存回模块」或「取消编辑」`); state.activeCanvasId = tab.dataset.canvasId; resetSelection(); render(); markDirty(); });
