multiSelectPanel.addEventListener("click", (e) => { const a = e.target.closest("[data-action]")?.dataset.action; if (a === "save-module") saveSelectionAsModule(); if (a === "clear-multi-select") clearMultiSelect(); });
moduleEditBar.addEventListener("click", (e) => { const a = e.target.closest("[data-action]")?.dataset.action; if (a === "save-module-edit") saveModuleEdit(); if (a === "cancel-module-edit") cancelModuleEdit(); });
moduleModal.addEventListener("click", (e) => { const action = e.target.closest("[data-action]")?.dataset.action; if (action === "close-modules") return closeModuleModal(); if (e.target.closest(".modal-backdrop") && !e.target.closest(".modal")) return closeModuleModal(); const btn = e.target.closest("[data-module-action]"); if (!btn) return; const id = btn.closest(".module-item")?.dataset.moduleId; if (!id) return; const mAction = btn.dataset.moduleAction; if (mAction === "place") placeModuleAtCenter(id); if (mAction === "rename") renameModule(id); if (mAction === "delete") deleteModule(id); if (mAction === "edit") beginModuleEdit(id); });
nodeLayer.addEventListener("click", (e) => { const resizeToggle = e.target.closest(".resize-toggle"); if (!resizeToggle) return; e.preventDefault(); e.stopPropagation(); if (activeTool !== "select") setTool("select"); resizeModeNodeId = resizeModeNodeId === resizeToggle.dataset.nodeId ? null : resizeToggle.dataset.nodeId; renderNodes(); updateStatus(); });
nodeLayer.addEventListener("pointerdown", (e) => { blurInspector(); const labelTarget = e.target.closest(".node-label"); if (labelTarget) { const labelNode = e.target.closest(".node"), labelId = labelNode?.dataset.nodeId, now = Date.now(); if (activeTool === "connector") { lastLabelClick = null; } else if (editing && editing.nodeId === labelId) { return; } else if (lastLabelClick && lastLabelClick.nodeId === labelId && now - lastLabelClick.time < 400) { lastLabelClick = null; e.preventDefault(); e.stopPropagation(); beginEdit(labelId); return; } else { lastLabelClick = { nodeId: labelId, time: now }; } } else { lastLabelClick = null; } const resizeToggle = e.target.closest(".resize-toggle"); if (resizeToggle) { e.preventDefault(); e.stopPropagation(); return; } const resizeHandle = e.target.closest(".resize-handle"); if (resizeHandle) return beginResize(e, resizeHandle.dataset.nodeId, resizeHandle.dataset.handle); const port = e.target.closest(".port"), el = e.target.closest(".node"); if (!el) return; const id = el.dataset.nodeId; if (port) { e.preventDefault(); e.stopPropagation(); resizeModeNodeId = null; connecting = { sourceId: id, side: port.dataset.side, pointerId: e.pointerId }; connectorSourceId = id; updateTemporaryEdge(e.clientX, e.clientY); renderNodes(); capturePointer(e.pointerId); return; } if (activeTool === "connector") { e.preventDefault(); if (!connectorSourceId) { connectorSourceId = id; selectedNodeId = id; resizeModeNodeId = null; selectedEdgeId = null; selectedNodeIds = new Set(); render(); } else { addEdge(connectorSourceId, id); connectorSourceId = null; } return; } if (e.shiftKey && (activeTool === "select" || activeTool === "marquee")) { e.preventDefault(); toggleMultiSelect(id); return; } if (activeTool !== "select") return; e.preventDefault(); const groupIds = selectedNodeIds.size && selectedNodeIds.has(id) ? [...selectedNodeIds] : [id], groupNodes = activeCanvas().nodes.filter((x) => groupIds.includes(x.id)); selectedNodeId = groupIds.length === 1 ? id : null; resizeModeNodeId = null; selectedEdgeId = null; selectedNodeIds = groupIds.length === 1 ? new Set() : new Set(groupIds); const histLen = canvasStack(activeCanvas().id).history.length; drag = { nodeId: id, pointerId: e.pointerId, startX: e.clientX, startY: e.clientY, items: groupNodes.map((x) => ({ id: x.id, originX: x.x, originY: x.y })), changed: false, histLen }; pushHistory(); renderNodes(); renderEdges(); capturePointer(e.pointerId); renderInspector(); updateStatus(); });
nodeLayer.addEventListener("focusout", (e) => { if (e.target.matches(".node-label[contenteditable='true']")) finishEdit(e.target); });
edgeGroup.addEventListener("click", (e) => { const edge = e.target.closest(".edge"); if (!edge) return; selectedEdgeId = edge.dataset.edgeId; selectedNodeId = null; selectedNodeIds = new Set(); resizeModeNodeId = null; renderNodes(); renderEdges(); renderInspector(); updateStatus(); });
viewport.addEventListener("pointerdown", (e) => { blurInspector(); if (connecting) return; if (activeTool === "marquee") { if (e.button !== 0) return; e.preventDefault(); startMarquee(e); return; } if (e.target.closest?.(".node") || e.target.closest?.("button") || e.target.closest?.(".module-edit-bar")) return; if (e.target.closest?.(".edge")) return; if (editing) { commitPendingEdit(); render(); return; } if (activeTool !== "select" && activeTool !== "connector") { if (e.button === 0) { e.preventDefault(); addNode(activeTool, e.clientX, e.clientY); } return; } if (e.button !== 0 && e.button !== 1) return; if (selectedNodeId || selectedEdgeId || selectedNodeIds.size || resizeModeNodeId || connectorSourceId) { resetSelection(); render(); } e.preventDefault(); const v = activeCanvas().view || { zoom: 1, panX: 0, panY: 0 }; pan = { pointerId: e.pointerId, startX: e.clientX, startY: e.clientY, originX: v.panX, originY: v.panY }; viewport.classList.add("is-panning"); });
document.addEventListener("pointermove", (e) => { if (connecting) return updateTemporaryEdge(e.clientX, e.clientY); if (marqueeDrag) return updateMarquee(e); if (resizing) return updateResize(e); if (drag) { const v = activeCanvas().view || { zoom: 1 }, canvas = activeCanvas(), dx = (e.clientX - drag.startX) / v.zoom, dy = (e.clientY - drag.startY) / v.zoom; let moved = false; drag.items.forEach((item) => { const n = canvas.nodes.find((x) => x.id === item.id); if (!n) return; n.x = clamp(Math.round(item.originX + dx), 10, Math.max(10, 2400 - n.w)); n.y = clamp(Math.round(item.originY + dy), 10, Math.max(10, 1500 - n.h)); if (n.x !== item.originX || n.y !== item.originY) moved = true; }); if (moved) drag.changed = true; renderNodes(); renderEdges(); markDirty(); } if (pan) { const v = activeCanvas().view || { zoom: 1, panX: 0, panY: 0 }; v.panX = pan.originX + e.clientX - pan.startX; v.panY = pan.originY + e.clientY - pan.startY; clampPan(v); activeCanvas().view = v; renderTransform(); markDirty(); } });
document.addEventListener("pointerup", (e) => { if (connecting) return finishConnection(e); if (marqueeDrag) return finishMarquee(); if (resizing) return finishResize(); if (drag) { if (!drag.changed) canvasStack(activeCanvas().id).history.length = drag.histLen; else saveLocal("节点位置已保存"); drag = null; render(); } if (pan) { pan = null; viewport.classList.remove("is-panning"); } });
document.addEventListener("pointercancel", () => { if (drag) { if (!drag.changed) canvasStack(activeCanvas().id).history.length = drag.histLen; drag = null; } cancelResize(); cancelMarquee(); pan = null; connecting = null; connectorSourceId = null; temporaryEdge.hidden = true; viewport.classList.remove("is-panning"); render(); });
// 兜底：指针捕获被系统回收（例如指针设备拔出、浏览器强制释放）时，把进行中的交互状态收干净，避免虚线粘在光标上。
document.addEventListener("lostpointercapture", (e) => { if (connecting && connecting.pointerId === e.pointerId) { connecting = null; connectorSourceId = null; temporaryEdge.hidden = true; render(); return; } if (resizing && resizing.pointerId === e.pointerId) return cancelResize(); if (drag && drag.pointerId === e.pointerId) { if (!drag.changed) canvasStack(activeCanvas().id).history.length = drag.histLen; drag = null; render(); return; } if (marqueeDrag && marqueeDrag.pointerId === e.pointerId) { cancelMarquee(); render(); return; } if (pan && pan.pointerId === e.pointerId) { pan = null; viewport.classList.remove("is-panning"); } });
viewport.addEventListener("wheel", (e) => { e.preventDefault(); const v = activeCanvas().view || { zoom: 1, panX: 0, panY: 0 }; if (e.ctrlKey || e.metaKey) changeZoom(v.zoom + (e.deltaY > 0 ? -.08 : .08), e.clientX - viewport.getBoundingClientRect().left, e.clientY - viewport.getBoundingClientRect().top); else { const unit = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? viewport.clientHeight : 1; v.panX -= e.deltaX * unit; v.panY -= e.deltaY * unit; clampPan(v); activeCanvas().view = v; renderTransform(); markDirty(); } }, { passive: false });
viewport.addEventListener("dblclick", (e) => { if (!e.target.closest?.(".node, .port") && activeTool === "text") addNode("text", e.clientX, e.clientY); });
document.addEventListener("keydown", (e) => { if (editing) { if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") { e.preventDefault(); cancelEdit(); return; } if (e.key === "Escape") { e.preventDefault(); cancelEdit(); return; } if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); e.target.blur(); } return; } if (focusInEditableControl()) return; if (!moduleModal.hidden) { if (e.key === "Escape") { e.preventDefault(); closeModuleModal(); return; } if (e.key === "Tab") { trapTabInModal(e); return; } if ((e.ctrlKey || e.metaKey) && ["z", "y", "s"].includes(e.key.toLowerCase())) { e.preventDefault(); return; } return; } if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") { e.preventDefault(); undo(); return; } if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "y") { e.preventDefault(); redo(); return; } if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "s") { e.preventDefault(); saveLocal(); showToast("已保存到本机"); return; } if (e.key === "Escape") { if (marqueeDrag) return cancelMarquee(); if (resizing) return cancelResize(); if (connecting || selectedNodeId || selectedEdgeId || selectedNodeIds.size || resizeModeNodeId || connectorSourceId) { resetSelection(); render(); return; } if (moduleEditing && window.confirm(`退出模块「${moduleEditing.name}」的编辑？画布上这份内容会留着，原模块不改动。`)) return cancelModuleEdit(); return; } if (e.ctrlKey || e.metaKey || e.altKey) return; if (e.key.toLowerCase() === "m") { setTool("marquee"); return; } if (e.key === "Delete" || e.key === "Backspace") deleteSelection(); if (e.key.toLowerCase() === "v") setTool("select"); if (e.key.toLowerCase() === "t") setTool("text"); });
